before:
Complete local Rust example; the app itself does not execute it:
```rust
use std::fmt;
struct Session { minutes: u32 }
impl fmt::Display for Session {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{} min", self.minutes)
    }
}
fn main() {
    let session = Session { minutes: 15 };
    println!("{session}");
}
```

